import {Screen2 as Material} from "./0Describing the UI/section1"

export default function () {
  return (
    <>
    <Pack />
    </>
  );
}


function Pack({ok, content}) {
  if(ok) {
    return <li>
      <del>{content}</del>
    </li>
  }
  return <li>{content}</li>
}
